    await writeFile(path.join(backend, "src", "routes", "index.js"), `import { Router } from "express";\nimport { z } from "zod";\nimport { sequelize } from "../db.js";\nimport { StockItem } from "../models/StockItem.js";\nimport { requireAuth, allowRoles } from "../middleware.js";\nexport const router = Router();\nrouter.get("/", requireAuth, allowRoles("SUPER_ADMIN", "INVENTORY", "MANAGER"), async (req, res, next) => { try { res.json(await StockItem.findAll({ order: [["updatedAt", "DESC"]], limit: 500 })); } catch (error) { next(error); } });\nrouter.post("/", requireAuth, allowRoles("SUPER_ADMIN", "INVENTORY"), async (req, res, next) => { try { const input = z.object({ productId: z.string().uuid(), quantity: z.coerce.number().int().min(0), reorderLevel: z.coerce.number().int().min(0).optional() }).parse(req.body); const [item] = await StockItem.findOrCreate({ where: { productId: input.productId }, defaults: input }); res.status(201).json(item); } catch (error) { next(error); } });\nrouter.post("/reserve", requireAuth, async (req, res, next) => { try { const input = z.object({ productId: z.string().uuid(), quantity: z.coerce.number().int().positive().max(100) }).parse(req.body); const item = await sequelize.transaction(async (transaction) => { const stock = await StockItem.findOne({ where: { productId: input.productId }, transaction, lock: transaction.LOCK.UPDATE }); if (!stock || stock.quantity - stock.reserved < input.quantity) throw Object.assign(new Error("Insufficient available stock"), { status: 409 }); await stock.increment("reserved", { by: input.quantity, transaction }); return stock; }); res.json(item); } catch (error) { next(error); } });\nrouter.post("/release", requireAuth, async (req, res, next) => { try { const input = z.object({ productId: z.string().uuid(), quantity: z.coerce.number().int().positive() }).parse(req.body); const item = await sequelize.transaction(async (transaction) => { const stock = await StockItem.findOne({ where: { productId: input.productId }, transaction, lock: transaction.LOCK.UPDATE }); if (!stock) return null; await stock.decrement("reserved", { by: Math.min(input.quantity, stock.reserved), transaction }); return stock; }); res.json(item); } catch (error) { next(error); } });\n`);
