const authBootstrap = 'if (process.env.SEED_ADMIN_EMAIL && process.env.SEED_ADMIN_PASSWORD) { if (process.env.SEED_ADMIN_PASSWORD.length < 16) throw new Error("SEED_ADMIN_PASSWORD must be at least 16 characters"); const email = process.env.SEED_ADMIN_EMAIL.trim().toLowerCase(); const [user, created] = await User.findOrCreate({ where: { email }, defaults: { name: "ShopZone Administrator", email, passwordHash: await (await import("bcryptjs")).default.hash(process.env.SEED_ADMIN_PASSWORD, 12), role: "SUPER_ADMIN", active: true } }); if (!created && user.role !== "SUPER_ADMIN") throw new Error("Seed email already belongs to a non-admin account; choose a different SEED_ADMIN_EMAIL"); console.info(created ? "Created the configured super-admin." : "Configured super-admin already exists."); } else console.info("Authentication schema is ready; set SEED_ADMIN_EMAIL and SEED_ADMIN_PASSWORD to bootstrap a super-admin.");';
await writeFile(authSeedPath, authSeedSource.replace('console.info("Authentication schema is ready.");', authBootstrap));

await dbClient.end();

const gatewayDir = path.join(root, "infrastructure", "api-gateway");
await mkdir(path.join(gatewayDir, "src"), { recursive: true });
const gatewayOrigins = ["http://localhost:3000", ...modules.map((module) => `http://localhost:${module.frontendPort}`)].join(",");
await writeFile(path.join(gatewayDir, ".env"), `NODE_ENV=development\nPORT=5000\nCORS_ORIGINS=${gatewayOrigins}\n`);
await writeFile(path.join(gatewayDir, ".env.example"), `NODE_ENV=development\nPORT=5000\nCORS_ORIGINS=${gatewayOrigins}\n`);
await writeFile(path.join(gatewayDir, "package.json"), JSON.stringify({ name: "@shopzone/api-gateway", version: "1.0.0", private: true, type: "module", scripts: { dev: "node --watch src/server.js", start: "node src/server.js", stop: "node ../../scripts/stop-port.js 4000" }, dependencies: { axios: "^1.12.2", cors: "^2.8.5", dotenv: "^16.6.1", express: "^5.1.0", helmet: "^8.1.0" } }, null, 2) + "\n");
await writeFile(path.join(gatewayDir, "src", "server.js"), `import dotenv from "dotenv";\nimport { fileURLToPath } from "node:url";\nimport express from "express";\nimport cors from "cors";\nimport helmet from "helmet";\nimport axios from "axios";\nimport { z } from "zod";\ndotenv.config({ path: fileURLToPath(new URL("../.env", import.meta.url)) });\nconst config = z.object({ PORT: z.coerce.number().default(5000), CORS_ORIGIN: z.string().url() }).parse(process.env);\nconst services = ${JSON.stringify(Object.fromEntries(modules.map((module) => [module.api, { port: module.backendPort, name: module.key }])), null, 2)};\nconst app = express(); app.disable("x-powered-by"); app.use(helmet()); app.use(cors({ origin: config.CORS_ORIGIN, credentials: true, allowedHeaders: ["Content-Type", "Authorization"] })); app.use(express.json({ limit: "100kb" }));\napp.get("/health", (_req, res) => res.json({ status: "ok", gateway: "shopzone-api-gateway", routes: Object.keys(services) }));\nfor (const [prefix, service] of Object.entries(services)) { app.use("/api/" + prefix, async (req, res) => { try { const response = await axios({ method: req.method, url: \`http://127.0.0.1:\${service.port}/api/\${prefix}\${req.url}\`, data: req.body, headers: { ...(req.headers.authorization ? { authorization: req.headers.authorization } : {}), ...(req.headers.cookie ? { cookie: req.headers.cookie } : {}), ...(req.headers["content-type"] ? { "content-type": req.headers["content-type"] } : {}) }, timeout: 8000, validateStatus: () => true, responseType: "arraybuffer" }); res.status(response.status); for (const header of ["content-type", "set-cookie", "cache-control"]) if (response.headers[header]) res.setHeader(header, response.headers[header]); res.send(Buffer.from(response.data)); } catch (error) { res.status(error.code === "ECONNREFUSED" ? 503 : 504).json({ error: \`\${service.name} service is unavailable\` }); } }); }\napp.use((_req, res) => res.status(404).json({ error: "No gateway route for this path" }));\napp.listen(config.PORT, () => console.info("ShopZone API Gateway listening on http://localhost:" + config.PORT));\n`);
const gatewayServerPath = path.join(gatewayDir, "src", "server.js");
const gatewayServerSource = await readFile(gatewayServerPath, "utf8");
await writeFile(gatewayServerPath, gatewayServerSource
  .replace('const config = z.object({ PORT: z.coerce.number().default(5000), CORS_ORIGIN: z.string().url() }).parse(process.env);', 'const config = z.object({ PORT: z.coerce.number().default(5000), CORS_ORIGINS: z.string().min(1) }).parse(process.env);\nconst allowedOrigins = new Set(config.CORS_ORIGINS.split(",").map((origin) => origin.trim()));')
  .replace('app.use(cors({ origin: config.CORS_ORIGIN, credentials: true, allowedHeaders: ["Content-Type", "Authorization"] }));', 'app.use(cors({ origin: (origin, callback) => callback(null, !origin || allowedOrigins.has(origin)), credentials: true, allowedHeaders: ["Content-Type", "Authorization"] }));'));

const hostDir = path.join(root, "apps", "host");
await mkdir(path.join(hostDir, "src"), { recursive: true });
await writeFile(path.join(hostDir, "package.json"), JSON.stringify({ name: "@shopzone/host", version: "1.0.0", private: true, type: "module", scripts: { dev: "vite --host 0.0.0.0", build: "vite build", preview: "vite preview --host 0.0.0.0", stop: "node ../../scripts/stop-port.js 3000" }, dependencies: { bootstrap: "^5.3.8", react: "^19.1.1", "react-dom": "^19.1.1" }, devDependencies: { "@originjs/vite-plugin-federation": "^1.4.1", "@vitejs/plugin-react": "^5.0.4", vite: "^6.4.1" } }, null, 2) + "\n");
const remotes = Object.fromEntries(modules.map((module) => [module.key, `${module.key}_mfe: \`http://localhost:${module.frontendPort}/assets/remoteEntry.js\``]));
await writeFile(path.join(hostDir, "vite.config.js"), `import { defineConfig } from "vite";\nimport react from "@vitejs/plugin-react";\nimport federation from "@originjs/vite-plugin-federation";\nexport default defineConfig({ plugins: [react(), federation({ name: "shopzone_host", remotes: { ${Object.entries(remotes).map(([, value]) => value).join(",\n")} }, shared: ["react", "react-dom"] })], server: { port: 3000, strictPort: true, cors: true }, preview: { port: 3000, strictPort: true }, build: { target: "esnext", minify: false, cssCodeSplit: false } });\n`);
await writeFile(path.join(hostDir, "index.html"), `<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>ShopZone</title></head><body><div id="root"></div><script type="module" src="/src/main.jsx"></script></body></html>\n`);
const remoteImports = modules.map((module) => `const ${module.key}Remote = lazy(() => import("${module.key}_mfe/App"));`).join("\n");
const remoteRoutes = modules.map((module) => `  "${module.key}": { title: "${module.title}", component: ${module.key}Remote },`).join("\n");
await writeFile(path.join(hostDir, "src", "App.jsx"), `import { lazy, Suspense, useState } from "react";\n${remoteImports}\nconst remotes = {\n${remoteRoutes}\n};\nexport default function App() { const initial = location.pathname.split("/").filter(Boolean)[0] || "products"; const [selected, setSelected] = useState(remotes[initial] ? initial : "products"); const Remote = remotes[selected].component; return <div className="shell"><header><a className="logo" href="/">ShopZone</a><span>Independent commerce services</span><a href="http://localhost:5000/health" target="_blank" rel="noreferrer">Gateway health</a></header><nav>{Object.entries(remotes).map(([key, remote]) => <button className={selected === key ? "active" : ""} key={key} onClick={() => { setSelected(key); history.pushState({}, "", "/" + key); }}>{remote.title}</button>)}</nav><main><Suspense fallback={<div className="loading">Connecting to {remotes[selected].title} remote…</div>}><Remote /></Suspense></main><footer>Each module owns its frontend, API, database, migrations and run lifecycle.</footer></div>; }\n`);
await writeFile(path.join(hostDir, "src", "main.jsx"), `import React from "react";\nimport { createRoot } from "react-dom/client";\nimport "bootstrap/dist/css/bootstrap.min.css";\nimport "./style.css";\nimport App from "./App.jsx";\ncreateRoot(document.getElementById("root")).render(<React.StrictMode><App /></React.StrictMode>);\n`);
await writeFile(path.join(hostDir, "src", "style.css"), `:root{font-family:Inter,Arial,sans-serif;color:#202720;background:#f7f5ee}*{box-sizing:border-box}body{margin:0;background:#f7f5ee}.shell header{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:16px clamp(16px,4vw,48px);background:#fffefa;border-bottom:1px solid #e8e4d8}.logo{font:700 26px Georgia,serif;color:#33442f}.shell header span,.shell header>a:last-child{font-size:13px;color:#686e65}.shell nav{display:flex;gap:8px;overflow-x:auto;padding:12px clamp(16px,4vw,48px);background:#33442f}.shell nav button{border:1px solid #ffffff3b;background:transparent;color:#fff;padding:9px 13px;white-space:nowrap;cursor:pointer}.shell nav button.active{background:#fffefa;color:#33442f}.shell main{min-height:70vh}.shell footer{padding:22px;text-align:center;color:#696d63;font-size:13px}.loading{padding:60px;text-align:center}\n`);

